import type * as THREE from 'three';
import type { DesignLibrary } from './library';

/** What a demonstration course was laid with: its size and place, and the materials of its parts. */
export interface DesignCourse {
  x?: number;
  y?: number;
  z?: number;
  ry?: number;
  w: number;
  l: number;
  slabH?: number;
  felt: THREE.Material;
  rail: THREE.Material;
  slab: THREE.Material;
  post?: THREE.Material;
}

export interface DesignHooks {
  /** Called with each demonstration course: what it was asked for, the group it was built in, and the height of its playing surface. */
  course(options: DesignCourse, group: THREE.Group, top: number): void;
  /** Called with the sign that stands by the tee, which says "1". */
  sign(group: THREE.Group): void;
  /** Wraps a texture or material maker so that it makes one thing per set of arguments. */
  memo<F extends (...args: never[]) => unknown>(kind: string, make: F): F;
}

/**
 * Builds the scene of one world's picture (`name` is the world's name in the design
 * project), as the design project drew it: generated by scripts/world-sets.mjs. A name
 * the design does not know gets a scene with no camera.
 */
export function build(
  L: DesignLibrary,
  name: string,
  hooks: DesignHooks,
): { scene: THREE.Scene; camera?: THREE.PerspectiveCamera; focus?: number };
